/*
 * chat المساعد (Platform admin and AI assistant داخل نظام Network).
 * Log يبقى in Page ويُرسل آخره مع Every سؤال. خصائص اختيارية on [data-chat]:
 *   data-store        Key Save Chat لهذه الجلسة (تبقى yet مغادرة Page والعودة)
 *   data-confirm-url  مسار Run Actions التي يجهّزها المساعد yet ضغط “Confirm”
 */
(function (window, document) {
  'use strict';
  var box = document.querySelector('[data-chat]');
  if (!box || box.hasAttribute('data-disabled')) { return; }
  var log = box.querySelector('[data-chat-log]');
  var form = box.querySelector('[data-chat-form]');
  var input = form.querySelector('textarea');
  var clearBtn = box.querySelector('[data-chat-clear]');
  var store = box.getAttribute('data-store');
  var confirmUrl = box.getAttribute('data-confirm-url');
  var emptyHtml = (log.querySelector('[data-chat-empty]') || {}).outerHTML || '';
  var history = [];
  var busy = false;

  function icon(name) { return window.SN && SN.icon ? SN.icon(name) : ''; }
  function save() {
    if (!store) { return; }
    try { sessionStorage.setItem(store, JSON.stringify(history.slice(-24))); } catch (e) { /* Storage Unavailable */ }
  }
  function toBottom() { log.scrollTop = log.scrollHeight; }

  function bubble(role, text) {
    var empty = log.querySelector('[data-chat-empty]');
    if (empty) { empty.remove(); }
    if (clearBtn) { clearBtn.hidden = false; }
    var el = document.createElement('div');
    el.className = 'chat-msg is-' + role;
    el.textContent = text;
    log.appendChild(el);
    toBottom();
    return el;
  }

  // ---------------------------------------------------------------------
  // إجراء جهّزه المساعد: بطاقة in Chat, ونافذة فيها What will run بالضبط وحقول يراجعها User
  // ويعدّلها, and no يُنفَّذ شيء إلا بضغط “OK”. Message text النصية يُفتح in Page الإرسال للمراجعة.
  // ---------------------------------------------------------------------
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) { n.className = cls; }
    if (text !== undefined && text !== null) { n.textContent = text; }
    return n;
  }
  function fieldNode(f, idx) {
    var wrap = el('div', 'field ai-field' + (f.type === 'checkbox' ? ' is-check' : ''));
    var id = 'ai-f-' + idx + '-' + f.name;
    if (f.type === 'checkbox') {
      var lab = el('label', 'switch');
      var cb = el('input'); cb.type = 'checkbox'; cb.name = f.name; cb.checked = !!f.value; cb.id = id;
      lab.appendChild(cb); lab.appendChild(el('span', 'track')); lab.appendChild(el('span', '', f.label));
      wrap.appendChild(lab);
      return wrap;
    }
    var label = el('label', '', f.label); label.htmlFor = id;
    if (f.required) { var req = el('span', 'req', ' *'); label.appendChild(req); }
    wrap.appendChild(label);
    var input;
    if (f.type === 'select') {
      input = el('select', 'input');
      (f.options || []).forEach(function (o) {
        var op = el('option', '', o.l); op.value = String(o.v);
        if (String(o.v) === String(f.value)) { op.selected = true; }
        input.appendChild(op);
      });
    } else if (f.type === 'multi') {
      input = el('div', 'ai-multi');
      input.setAttribute('role', 'group');
      var chosen = (f.value || []).map(String);
      (f.options || []).forEach(function (o) {
        var l = el('label', 'ai-chip');
        var c = el('input'); c.type = 'checkbox'; c.name = f.name; c.value = String(o.v); c.checked = chosen.indexOf(String(o.v)) !== -1;
        l.appendChild(c); l.appendChild(el('span', '', o.l));
        input.appendChild(l);
      });
    } else if (f.type === 'textarea') {
      input = el('textarea', 'input' + (f.mono ? ' input-ltr mono' : ''));
      input.rows = 4; input.value = f.value == null ? '' : f.value;
    } else {
      input = el('input', 'input' + (f.mono ? ' input-ltr mono' : ''));
      input.type = f.type === 'number' ? 'number' : 'text';
      if (f.type === 'number') {
        input.inputMode = 'decimal';
        if (f.min !== undefined) { input.min = f.min; }
        if (f.max !== undefined) { input.max = f.max; }
        input.step = f.step || '1';
      }
      input.value = f.value == null ? '' : f.value;
      if (f.readonly) { input.readOnly = true; input.classList.add('is-readonly'); }
    }
    if (f.type !== 'multi') { input.name = f.name; input.id = id; if (f.required) { input.required = true; } }
    wrap.appendChild(input);
    if (f.hint) { wrap.appendChild(el('div', 'hint', f.hint)); }
    return wrap;
  }
  function collect(form, fields) {
    var out = {};
    fields.forEach(function (f) {
      if (f.type === 'multi') {
        out[f.name] = Array.prototype.map.call(form.querySelectorAll('input[name="' + f.name + '"]:checked'), function (c) { return c.value; });
      } else if (f.type === 'checkbox') {
        var c = form.querySelector('input[name="' + f.name + '"]');
        out[f.name] = c && c.checked ? 1 : 0;
      } else {
        var i = form.querySelector('[name="' + f.name + '"]');
        out[f.name] = i ? i.value : '';
      }
    });
    return out;
  }
  function rowsTable(rows) {
    var keys = [];
    rows.forEach(function (r) { Object.keys(r).forEach(function (k) { if (keys.indexOf(k) === -1 && keys.length < 8) { keys.push(k); } }); });
    var wrap = el('div', 'table-wrap ai-rows');
    var t = el('table', 'table table-compact');
    var thead = el('thead'); var tr = el('tr');
    keys.forEach(function (k) { tr.appendChild(el('th', '', k)); });
    thead.appendChild(tr); t.appendChild(thead);
    var tb = el('tbody');
    rows.forEach(function (r) {
      var row = el('tr');
      keys.forEach(function (k) { var td = el('td', 'mono', r[k] === undefined ? '' : String(r[k])); td.dir = 'ltr'; row.appendChild(td); });
      tb.appendChild(row);
    });
    t.appendChild(tb); wrap.appendChild(t);
    return wrap;
  }
  var dlg = null;
  function dialogFor(a, card) {
    if (dlg) { dlg.remove(); }
    dlg = el('dialog', 'modal modal-lg ai-act' + (a.danger ? ' is-danger' : ''));
    var form = el('form', ''); form.method = 'dialog'; form.noValidate = false;
    var head = el('div', 'modal-head');
    var h = el('h3'); h.innerHTML = icon(a.danger ? 'triangle-alert' : 'wand-sparkles'); h.appendChild(document.createTextNode(a.title));
    var x = el('button', 'btn btn-ghost btn-icon btn-sm'); x.type = 'button'; x.setAttribute('aria-label', 'Close'); x.innerHTML = icon('x');
    head.appendChild(h); head.appendChild(x);
    var body = el('div', 'modal-body');
    var what = el('div', 'notice ai-what' + (a.danger ? ' notice-warning' : ''));
    what.innerHTML = icon('info');
    var wt = el('div');
    wt.appendChild(el('div', 'notice-title', 'What will run'));
    wt.appendChild(el('div', 'text-sm', a.summary || a.detail || ''));
    what.appendChild(wt);
    body.appendChild(what);
    var grid = el('div', 'ai-fields');
    (a.fields || []).forEach(function (f, i) { grid.appendChild(fieldNode(f, i)); });
    body.appendChild(grid);
    var msg = el('div', 'notice notice-danger ai-msg'); msg.hidden = true;
    body.appendChild(msg);
    var result = el('div', 'ai-result'); result.hidden = true;
    body.appendChild(result);
    var foot = el('div', 'modal-foot');
    var cancel = el('button', 'btn', 'Cancel'); cancel.type = 'button';
    var ok = el('button', 'btn ' + (a.danger ? 'btn-danger' : 'btn-primary')); ok.type = 'submit';
    ok.innerHTML = icon('check'); ok.appendChild(document.createTextNode(a.button || 'OK'));
    foot.appendChild(cancel); foot.appendChild(ok);
    form.appendChild(head); form.appendChild(body); form.appendChild(foot);
    dlg.appendChild(form);
    document.body.appendChild(dlg);
    var close = function () { window.SN.closeModal(dlg); };
    x.addEventListener('click', close);
    cancel.addEventListener('click', function () {
      if (!card.classList.contains('is-done')) { card.settle('is-cancelled', 'Cancelled'); }
      close();
    });
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (ok.disabled || card.classList.contains('is-done')) { return; }
      if (!form.reportValidity()) { return; }
      ok.disabled = true; cancel.disabled = true; ok.classList.add('is-loading'); msg.hidden = true;
      window.SN.api(confirmUrl, { method: 'POST', data: { id: a.id, values: collect(form, a.fields || []) }, silent: true })
        .then(function (r) {
          grid.hidden = true; what.hidden = true;
          result.hidden = false;
          result.innerHTML = '';
          var done = el('div', 'notice notice-success');
          done.innerHTML = icon('circle-check');
          done.appendChild(el('div', '', r.message));
          result.appendChild(done);
          if (r.rows && r.rows.length) { result.appendChild(rowsTable(r.rows)); }
          foot.innerHTML = '';
          if (r.url) { var go = el('a', 'btn', 'Open'); go.href = r.url; go.insertAdjacentHTML('afterbegin', icon('external-link')); foot.appendChild(go); }
          var fin = el('button', 'btn btn-primary', 'Done'); fin.type = 'button'; fin.addEventListener('click', close);
          foot.appendChild(fin);
          card.settle('is-done', r.message, r.url);
        })
        .catch(function (err) {
          msg.textContent = err.message;
          msg.hidden = false;
          ok.disabled = false; cancel.disabled = false; ok.classList.remove('is-loading');
          // Action الذي Finished مهلته لا يُعاد; غيره يبقى قابلاً to correct and Redo المحاولة
          if (!(err.data && err.data.retry)) { ok.disabled = true; card.settle('is-failed', err.message); }
        });
    });
    window.SN.openModal(dlg);
    return dlg;
  }
  function actionCard(a, autoOpen) {
    var card = el('div', 'chat-action');
    var head = el('div', 'chat-action-head');
    head.innerHTML = icon(a.type === 'sms' ? 'message-square' : (a.danger ? 'triangle-alert' : 'zap'));
    head.appendChild(el('b', '', a.title));
    var detail = el('div', 'chat-action-detail' + (a.type === 'sms' ? ' is-quote' : ''), a.summary || a.detail);
    var foot = el('div', 'chat-action-foot');
    card.appendChild(head); card.appendChild(detail); card.appendChild(foot);
    card.settle = function (cls, text, url) {
      card.classList.remove('is-done', 'is-failed', 'is-cancelled');
      card.classList.add(cls);
      foot.innerHTML = '';
      var s = el('span', 'chat-action-result');
      s.innerHTML = icon(cls === 'is-done' ? 'circle-check' : (cls === 'is-failed' ? 'circle-x' : 'ban'));
      s.appendChild(document.createTextNode(text));
      foot.appendChild(s);
      if (url) { var l = el('a', 'btn btn-ghost btn-xs', 'Open'); l.href = url; foot.appendChild(l); }
      toBottom();
    };
    if (a.url) {
      var link = el('a', 'btn btn-primary btn-sm');
      link.href = a.url;
      link.innerHTML = icon('send');
      link.appendChild(document.createTextNode(a.button));
      foot.appendChild(link);
    } else {
      var open = el('button', 'btn btn-primary btn-sm'); open.type = 'button';
      open.innerHTML = icon('app-window');
      open.appendChild(document.createTextNode('Open window'));
      foot.appendChild(open);
      open.addEventListener('click', function () { dialogFor(a, card); });
      if (autoOpen) { setTimeout(function () { dialogFor(a, card); }, 120); }
    }
    log.appendChild(card);
    toBottom();
  }
  function usage(r) {
    var t = box.querySelector('[data-chat-usage-text]'), bar = box.querySelector('[data-chat-usage-bar]');
    if (!t || typeof r.used !== 'number' || !r.limit) { return; }
    var fmt = window.SN && SN.fmtNum ? SN.fmtNum : String;
    t.textContent = '⁦' + fmt(r.used) + ' / ' + fmt(r.limit) + '⁩';
    var pct = Math.min(100, Math.round(r.used / r.limit * 100));
    bar.style.width = pct + '%';
    bar.parentNode.className = 'meter' + (pct >= 90 ? ' is-danger' : (pct >= 70 ? ' is-warning' : ''));
  }

  function send(text) {
    text = (text || '').trim();
    if (!text || busy) { return; }
    busy = true;
    bubble('user', text);
    history.push({ role: 'user', content: text });
    input.value = '';
    input.style.height = '';
    var wait = bubble('assistant', '');
    wait.classList.add('is-typing');
    window.SN.api(box.getAttribute('data-url'), { method: 'POST', data: { messages: history.slice(-12) }, silent: true })
      .then(function (r) {
        wait.classList.remove('is-typing');
        wait.textContent = r.text;
        history.push({ role: 'assistant', content: r.text });
        save();
        (r.actions || []).forEach(function (a, i) { actionCard(a, i === 0); });
        usage(r);
      })
      .catch(function (e) {
        wait.classList.remove('is-typing');
        wait.classList.add('is-error');
        wait.textContent = e.message;
        history.pop();
        if (e.data) { usage(e.data); }
      })
      .then(function () { busy = false; toBottom(); input.focus(); });
  }

  form.addEventListener('submit', function (e) { e.preventDefault(); send(input.value); });
  input.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(input.value); }
  });
  input.addEventListener('input', function () {
    input.style.height = 'auto';
    input.style.height = Math.min(input.scrollHeight, 140) + 'px';
  });
  log.addEventListener('click', function (e) {
    var b = e.target.closest('[data-chat-sample]');
    if (b) { send(b.textContent); }
  });
  if (clearBtn) {
    clearBtn.addEventListener('click', function () {
      if (busy) { return; }
      history = [];
      save();
      log.innerHTML = emptyHtml;
      clearBtn.hidden = true;
      input.focus();
    });
  }

  // Restore chat هذه الجلسة (Texts only; Actions المعلّقة لا تُستعاد وتُطلب from New)
  if (store) {
    try {
      var saved = JSON.parse(sessionStorage.getItem(store) || '[]');
      if (Array.isArray(saved)) {
        saved.forEach(function (m) {
          if (m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string') {
            history.push({ role: m.role, content: m.content });
            bubble(m.role, m.content);
          }
        });
      }
    } catch (e) { history = []; }
  }
})(window, document);
